#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    // If no numbers are provided, print EMPTY
    if (argc <= 1) {
        puts("EMPTY");
        return 0;
    }

    // The original binary limits the number of processed arguments to 64.
    const int MAX = 64;
    long values[MAX];
    int count = 0;

    // Insert each argument into a sorted list (ascending).
    for (int i = 1; i < argc && count < MAX; ++i) {
        long v = strtol(argv[i], NULL, 10);
        // Find insertion point to keep the array sorted.
        int pos = count;
        while (pos > 0 && values[pos - 1] > v) {
            values[pos] = values[pos - 1];
            --pos;
        }
        values[pos] = v;
        ++count;
    }

    // If no values were actually stored (should not happen unless all were filtered),
    // mimic the original behaviour.
    if (count == 0) {
        puts("EMPTY");
        return 0;
    }

    // Output the sorted numbers separated by a single space, followed by a newline.
    for (int i = 0; i < count; ++i) {
        if (i) putchar(' ');
        printf("%ld", values[i]);
    }
    putchar('\n');
    return 0;
}
